{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "How does the SARS-CoV-2 reinfection rate change over time? The global evidence from systematic review and meta-analysis",
      "reason": "The title explicitly includes the phrase 'systematic review and meta-analysis', thereby identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "How does the SARS-CoV-2 reinfection rate change over time? The global evidence from systematic review and meta-analysis",
